package netdiag

import (
	"log"

	"charm.land/bubbles/v2/textinput"
	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/forward"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/netcheck"
	"github.com/anthnel/devdesk/internal/shared"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/keymap"
)

// Init implements tea.Model
func (m *Model) Init() tea.Cmd {
	// The router runs Init on every entry. A source listing that came back while
	// another view was on screen went to that view, so a selector left open
	// would wait for it for good; it closes here instead.
	m.pathModel.closePicker()
	return tea.Batch(
		textinput.Blink,
		m.portsModel.initPorts(),
		m.interfacesModel.initInterfaces(),
		// The forwards live on the router, which broadcasts when they change.
		// A view built after the last change was not there for it, so it asks
		// once on the way in — the role sendJobsTo plays for the job registry.
		forward.Refresh,
	)
}

// Running reports whether a diagnostic is walking its stages now, which is what
// the router asks before it would rebuild the view: dropping it mid-run would
// discard the run without a word.
//
// A path trace counts too, even from another tab: it goes on there.
func (m *Model) Running() bool { return m.state == StateRunning || m.pathModel.running() }

// InEditMode implements FormView — true when a text input is active, so the
// router hands the key to the field rather than opening the command line.
func (m *Model) InEditMode() bool {
	switch m.activeTab {
	case tabPorts:
		return m.portsModel.InEditMode()
	case tabInterfaces:
		// The interfaces table has a search box now, where the Topology tab it
		// replaced had no input at all. Returning false here would let a ":"
		// typed into the query open the command line instead (Rule 111).
		return m.interfacesModel.InEditMode()
	case tabForward:
		return m.forwardModel.InEditMode()
	case tabPath:
		return m.pathModel.InEditMode()
	}
	if m.filterBar.InEditMode() {
		return true
	}
	if m.state == StateInput {
		return m.focusedField == fieldTarget || m.focusedField == fieldPort || m.focusedField == fieldDNSServer
	}
	return false
}

// Update implements tea.Model
func (m *Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.resizeInputs()
		m.filterBar.Resize(msg.Width)
		m.rebuildChecksTable()
		m.resizeDetailsViewport()
		m.portsModel.resize(msg.Width, msg.Height)
		m.interfacesModel.resize(msg.Width, msg.Height)
		m.forwardModel.resize(msg.Width, msg.Height)
		m.pathModel.resize(msg.Width, msg.Height)
		return m, nil

	// The router's animation frame: the blink phase of the Ports dot and of the
	// two footers that show the shared activity dot, whichever tab is on screen
	// so a tab never comes back with a frozen phase.
	case jobs.FrameMsg:
		m.portsModel.table.SetBlinkPhase(msg.Blink)
		m.footer.SetBlinkPhase(msg.Blink)
		m.interfacesModel.footer.SetBlinkPhase(msg.Blink)
		m.pathModel.footer.SetBlinkPhase(msg.Blink)
		return m, nil

	case stageDoneMsg:
		return m.handleStageDone(msg)

	// Ports sub-model messages.
	case portsTickMsg, portsDataMsg, portsKillResultMsg:
		var cmd tea.Cmd
		m.portsModel, cmd = m.portsModel.update(msg)
		return m, cmd

	// The terminal focus reaches the ports poll on every tab: its tick runs
	// whichever tab shows.
	case shared.TerminalFocusMsg:
		var cmd tea.Cmd
		m.portsModel, cmd = m.portsModel.update(msg)
		return m, cmd

	// Two tabs now ask before they act — Ports before a kill (§3.26), Forward
	// before dropping the connections a redirection is carrying — so the answer
	// goes to the tab that asked rather than to Ports unconditionally, which
	// would have confirmed a kill from the Forward tab's modal.
	case components.ConfirmModalYesMsg, components.ConfirmModalNoMsg:
		return m.routeConfirm(msg)

	// Forward sub-model messages. ChangedMsg is the router's broadcast, and it
	// reaches this view wherever it stands, on screen or not.
	case forward.ChangedMsg, forwardTickMsg, ForwardFormSubmitMsg, ForwardFormCancelMsg:
		var cmd tea.Cmd
		m.forwardModel, cmd = m.forwardModel.update(msg)
		return m, cmd

	// Path sub-model messages: a trace goes on, and its hops keep arriving,
	// whichever tab is on screen.
	case pathResolvedMsg, pathHopMsg, pathDoneMsg, pathSourcesMsg:
		var cmd tea.Cmd
		m.pathModel, cmd = m.pathModel.update(msg)
		return m, cmd

	// Topology sub-model messages
	case ifaceDataMsg:
		var cmd tea.Cmd
		m.interfacesModel, cmd = m.interfacesModel.update(msg)
		return m, cmd

	case tea.KeyPressMsg:
		return m.handleKey(msg)

	case tea.PasteMsg:
		return m.handlePaste(msg)
	}

	// Each tab holds its own footer, so an expiry has to be offered to all
	// five: the timer fires wherever the user has since navigated. The Path tab
	// also takes the cursor blink of its field.
	m.footer.Handle(msg)
	m.portsModel.footer.Handle(msg)
	m.interfacesModel.footer.Handle(msg)
	m.forwardModel.footer.Handle(msg)
	var cmd tea.Cmd
	m.pathModel, cmd = m.pathModel.update(msg)
	return m, cmd
}

// routeConfirm hands a confirmation answer to the tab that put the modal up.
func (m *Model) routeConfirm(msg tea.Msg) (*Model, tea.Cmd) {
	var cmd tea.Cmd
	if m.activeTab == tabForward {
		m.forwardModel, cmd = m.forwardModel.update(msg)
		return m, cmd
	}
	m.portsModel, cmd = m.portsModel.update(msg)
	return m, cmd
}

// handleStageDone records one stage's answers and starts the next.
func (m *Model) handleStageDone(msg stageDoneMsg) (*Model, tea.Cmd) {
	if msg.gen != m.runGen {
		return m, nil // a superseded run
	}
	m.results = msg.results
	m.rebuildChecksTable()

	steps := netcheck.Steps()
	if msg.next >= len(steps) {
		m.state = StateResults
		m.verdict = netcheck.Summarize(m.results.All())
		log.Printf("INFO [netdiag] run finished: verdict=%s over %d checks",
			m.verdict, len(m.results.All()))
		return m, nil
	}

	m.runStep = msg.next
	m.runStage = steps[msg.next]

	tg, err := m.buildTarget()
	if err != nil {
		// The form has not changed since the run started, so this cannot
		// normally fail. Reporting it beats continuing with a target nobody
		// can name.
		log.Printf("ERROR [netdiag] target became invalid mid-run: %v", err)
		m.state = StateResults
		return m, m.footer.Error("Run stopped — the target is no longer valid")
	}
	return m, runStageCmd(m.runGen, tg, m.checkSettings(), msg.next, m.results)
}

// handlePaste gives pasted text to the field that has the keyboard on the tab on
// screen. It never reaches the key handlers, so no action fires (Rule 111).
func (m *Model) handlePaste(msg tea.PasteMsg) (*Model, tea.Cmd) {
	var cmd tea.Cmd
	switch m.activeTab {
	case tabPorts:
		m.portsModel, cmd = m.portsModel.update(msg)
	case tabInterfaces:
		m.interfacesModel, cmd = m.interfacesModel.update(msg)
	case tabForward:
		m.forwardModel, cmd = m.forwardModel.update(msg)
	case tabPath:
		m.pathModel, cmd = m.pathModel.update(msg)
	default:
		switch {
		case m.filterBar.InEditMode():
			m.filterBar, cmd = m.filterBar.Update(msg)
			m.rebuildChecksTable()
		case m.state == StateInput:
			return m.updateActiveInput(msg)
		}
	}
	return m, cmd
}

func (m *Model) handleKey(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
	// A filter bar in edit mode claims every key before anything else, or a
	// query cannot contain the letters the view binds.
	if m.activeTab == tabDiagnostics && m.filterBar.InEditMode() {
		var cmd tea.Cmd
		m.filterBar, cmd = m.filterBar.Update(msg)
		m.rebuildChecksTable()
		return m, cmd
	}

	// An open selector holds every key, tab included: it is a mode.
	if m.activeTab == tabPath && m.pathModel.pickerOpen() {
		var cmd tea.Cmd
		m.pathModel, cmd = m.pathModel.update(msg)
		return m, cmd
	}

	// Tab / Shift+Tab cycles between the tabs (Rule 135)
	switch msg.String() {
	case "tab":
		m.activeTab = (m.activeTab + 1) % tabCount
		return m, nil
	case "shift+tab":
		m.activeTab = (m.activeTab + tabCount - 1) % tabCount
		return m, nil
	}

	// Route to active tab
	if m.activeTab == tabPorts {
		var cmd tea.Cmd
		m.portsModel, cmd = m.portsModel.update(msg)
		return m, cmd
	}
	if m.activeTab == tabInterfaces {
		var cmd tea.Cmd
		m.interfacesModel, cmd = m.interfacesModel.update(msg)
		return m, cmd
	}
	if m.activeTab == tabForward {
		var cmd tea.Cmd
		m.forwardModel, cmd = m.forwardModel.update(msg)
		return m, cmd
	}
	if m.activeTab == tabPath {
		var cmd tea.Cmd
		m.pathModel, cmd = m.pathModel.update(msg)
		return m, cmd
	}

	switch m.state {
	case StateInput:
		return m.handleKeyInput(msg)
	case StateRunning:
		return m.handleKeyRunning(msg)
	case StateResults:
		return m.handleKeyResults(msg)
	case StateDetails:
		return m.handleKeyDetails(msg)
	}
	return m, nil
}

// handleKeyRunning cancels the run. The stage in flight is awaited rather than
// interrupted — it is a network read that will time out on its own — and its
// result is discarded by the generation counter.
func (m *Model) handleKeyRunning(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
	if msg.String() != "esc" {
		return m, nil
	}
	m.runGen++
	m.state = StateResults
	m.verdict = netcheck.Summarize(m.results.All())
	m.rebuildChecksTable()
	return m, m.footer.Warn("Run cancelled — showing what completed")
}

func (m *Model) handleKeyInput(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
	switch msg.String() {
	case "down":
		m.moveFocus(1)
		return m, nil
	case "up":
		m.moveFocus(-1)
		return m, nil
	case "enter":
		// enter runs the checks from anywhere in the form, so the user need
		// not walk to the button first; only the Trace Path button means
		// something else.
		if m.focusedField == fieldTraceButton {
			return m.traceFromForm()
		}
		return m.StartRun()
	case "esc":
		return m, nil
	}
	return m.updateActiveInput(msg)
}

func (m *Model) moveFocus(delta int) {
	switch m.focusedField {
	case fieldTarget:
		m.targetInput.Blur()
	case fieldPort:
		m.portInput.Blur()
	case fieldDNSServer:
		m.dnsServerInput.Blur()
	}

	m.focusedField = (m.focusedField + delta + fieldCount) % fieldCount

	switch m.focusedField {
	case fieldTarget:
		m.targetInput.Focus()
	case fieldPort:
		m.portInput.Focus()
	case fieldDNSServer:
		m.dnsServerInput.Focus()
	}
}

func (m *Model) updateActiveInput(msg tea.Msg) (*Model, tea.Cmd) {
	var cmd tea.Cmd
	switch m.focusedField {
	case fieldTarget:
		m.targetInput, cmd = m.targetInput.Update(msg)
		m.revalidateTrace()
	case fieldPort:
		m.portInput, cmd = m.portInput.Update(msg)
	case fieldDNSServer:
		m.dnsServerInput, cmd = m.dnsServerInput.Update(msg)
	}
	return m, cmd
}

func (m *Model) handleKeyResults(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
	switch msg.String() {
	case "enter":
		return m.openDetails()
	case "esc":
		// No origin view means netdiag was opened directly (the command
		// line), so esc stays inside it and resets to the form, as it
		// always has. An origin means it was opened prefilled from
		// elsewhere (status's H, §3.66), and esc returns there instead.
		if m.OriginView == "" {
			return m.resetToForm()
		}
		origin := m.OriginView
		return m, func() tea.Msg { return BackToOriginMsg{Origin: origin} }
	case "ctrl+r":
		return m.StartRun()
	case "/":
		return m, m.filterBar.ActivateSearch()
	case "p":
		m.filterBar.SetTokenActive(problemsToken, !m.filterBar.IsTokenActive(problemsToken))
		m.rebuildChecksTable()
		return m, nil
	case keymap.Diagnose:
		return m.tracePathFromRoute()
	case keymap.New:
		// Always resets to the form, regardless of OriginView — the one way
		// to run a wholly new diagnostic without first leaving to wherever
		// this run was opened from. Found missing the day §3.66 shipped H:
		// esc alone left no way back to the form once an origin was set, and
		// re-entering netdiag through the command line landed on the same
		// frozen results with the same problem, since the cached view (and
		// its OriginView) is reused rather than rebuilt.
		return m.resetToForm()
	}
	return m, m.checksTable.Update(msg)
}

func (m *Model) handleKeyDetails(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
	switch msg.String() {
	case "esc":
		m.state = StateResults
		return m, nil
	case "up":
		m.detailsViewport.ScrollUp(1)
	case "down":
		m.detailsViewport.ScrollDown(1)
	case "pgup":
		m.detailsViewport.HalfPageUp()
	case "pgdown":
		m.detailsViewport.HalfPageDown()
	case "home":
		m.detailsViewport.GotoTop()
	case "end":
		m.detailsViewport.GotoBottom()
	}
	return m, nil
}

func (m *Model) openDetails() (*Model, tea.Cmd) {
	c, ok := m.checksTable.Selected()
	if !ok {
		return m, nil
	}
	m.selected = c
	m.state = StateDetails
	m.resizeDetailsViewport()
	m.detailsViewport.SetContent(m.renderDetailsContent(m.detailsViewport.Width()))
	m.detailsViewport.GotoTop()
	return m, nil
}

func (m *Model) resetToForm() (*Model, tea.Cmd) {
	m.state = StateInput
	m.focusedField = fieldTarget
	m.targetInput.Focus()
	m.results = netcheck.Results{}
	m.verdict = netcheck.Unknown
	m.filterBar.ClearSearch()
	m.filterBar.SetTokenActive(problemsToken, false)
	m.rebuildChecksTable()
	// Starting over severs the tie to wherever this run was opened from: the
	// next run is not "the monitor status sent here" anymore, so esc on its
	// results should not try to leave for a view this new target has nothing
	// to do with.
	m.OriginView = ""
	return m, nil
}

package netdiag

import (
	"fmt"
	"strings"
	"time"

	"charm.land/bubbles/v2/textinput"
	"charm.land/bubbles/v2/viewport"
	tea "charm.land/bubbletea/v2"
	"charm.land/lipgloss/v2"

	"github.com/anthnel/devdesk/internal/netcheck"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// View is the Bubble Tea v2 face of Render: the content only. The terminal
// state (alternate screen, colours) belongs to whoever owns the program.
func (m *Model) View() tea.View { return tea.NewView(m.Render()) }

// Render implements tea.Model
func (m *Model) Render() string {
	switch m.activeTab {
	case tabPorts:
		// The kill confirmation is centred over the tab, like every other
		// modal (Rule 112).
		if modal := m.portsModel.confirmModal; modal != nil {
			return lipgloss.Place(
				m.width, m.height,
				lipgloss.Center, lipgloss.Center,
				modal.View(),
				lipgloss.WithWhitespaceStyle(lipgloss.NewStyle().Background(theme.ColorBackground)),
			)
		}
		return m.portsModel.view()
	case tabInterfaces:
		return m.interfacesModel.view()
	case tabPath:
		return m.pathModel.view()
	case tabForward:
		// The stop confirmation is centred over the tab, like every other
		// modal (Rule 112).
		if modal := m.forwardModel.confirmModal; modal != nil {
			return lipgloss.Place(
				m.width, m.height,
				lipgloss.Center, lipgloss.Center,
				modal.View(),
				lipgloss.WithWhitespaceStyle(lipgloss.NewStyle().Background(theme.ColorBackground)),
			)
		}
		return m.forwardModel.view()
	}
	switch m.state {
	case StateInput:
		return m.renderInputForm()
	case StateRunning, StateResults:
		// The table stays on screen while the pipeline runs, filling in as each
		// stage lands. A body that swaps itself for a spinner loses its header
		// and its columns (Rule 139), and here it would also throw away the
		// rows already answered.
		return m.renderChecks()
	case StateDetails:
		return m.detailsViewport.View()
	}
	return ""
}

func (m *Model) renderInputForm() string {
	var b strings.Builder

	b.WriteString(m.renderTextInputField("Target", m.targetInput, fieldTarget))
	b.WriteString("\n")
	b.WriteString(m.renderTextInputField("Port", m.portInput, fieldPort))
	b.WriteString("\n")
	b.WriteString(m.renderTextInputField("DNS Server", m.dnsServerInput, fieldDNSServer))
	b.WriteString("\n\n")
	traceVariant := "primary"
	if !m.traceable().Enabled() {
		traceVariant = "disabled"
	}
	b.WriteString("  " + theme.RenderButton("Run Diagnostics", m.focusedField == fieldRunButton, "primary") +
		"  " + theme.RenderButton("Trace Path", m.focusedField == fieldTraceButton, traceVariant))

	return lipgloss.NewStyle().
		Padding(1).
		Background(theme.ColorBackground).
		Render(b.String())
}

func (m *Model) renderTextInputField(label string, input textinput.Model, fieldIdx int) string {
	prefix := "  "
	if m.focusedField == fieldIdx {
		prefix = theme.IconCircleSmall + " "
	}
	return theme.KeyStyle.Render(prefix+label+" "+theme.IconChevronRight+" ") + input.View()
}

// renderChecks draws the results table. An empty table — the run produced
// none, or the "problems" filter hid every one because they all passed —
// stays a table (Rule 139): its header and no rows. The Verdict header field
// already answers "did everything pass?" once there is a run to summarise.
func (m *Model) renderChecks() string {
	return m.checksTable.View()
}

// checkColumns describes the results table.
//
// A row is a question that got an answer, so the columns are the question, the
// answer, and what was observed — never the name of a tool.
func checkColumns() []datatable.Column[netcheck.Check] {
	return []datatable.Column[netcheck.Check]{
		{
			Title: "Check", Sizing: datatable.SizingContent, MinWidth: 20,
			Cell: func(c netcheck.Check) string { return c.Title },
		},
		{
			Title: "Verdict", Sizing: datatable.SizingFixed, MinWidth: 9,
			Cell:  verdictCell,
			Style: verdictStyle,
		},
		{
			Title: "Observed", Sizing: datatable.SizingContent, MinWidth: 20, Flex: 1,
			Cell: func(c netcheck.Check) string { return c.Summary },
		},
	}
}

// verdictCell is plain text: the colour is decided by Style (Rule 122).
func verdictCell(c netcheck.Check) string {
	switch c.Verdict {
	case netcheck.OK:
		return theme.IconOK + " OK"
	case netcheck.Warn:
		return theme.IconWarning + " WARN"
	case netcheck.Fail:
		return theme.IconError + " FAIL"
	case netcheck.NotApplicable:
		return theme.IconCanceled + " N/A"
	default:
		return theme.IconCanceled + " ?"
	}
}

// verdictStyle gives each verdict its own colour.
//
// Rule 122 reserves colour for what is worth spotting without reading, and its
// worked example — a container list where nearly every row is `running` —
// argues against colouring the nominal state. This column is the other case,
// and the difference is what the reader is doing: a diagnostic is read once,
// end to end, to find where it broke. Every row is a distinct question, there
// is no majority state to drown in, and the column *is* the answer. So the four
// outcomes are told apart at a glance, as Rule 121 has status indicators do.
//
// The one that is not a colour choice is UNKNOWN. It must not share N/A's dim:
// "no meaning here" and "we could not look" are the distinction the whole
// package is built on — the reason Verdict's zero value is Unknown and the
// reason SecretVerdict returns a *bool. Rendering them alike on screen would
// give back exactly what the types take care to keep apart.
func verdictStyle(c netcheck.Check) lipgloss.Style {
	switch c.Verdict {
	case netcheck.Fail:
		return theme.SeverityTextStyle("CRITICAL")
	case netcheck.Warn:
		return theme.SeverityTextStyle("MEDIUM")
	case netcheck.OK:
		return theme.StatusOKStyle
	case netcheck.Unknown:
		return theme.SeverityTextStyle("HIGH")
	default: // NotApplicable — nothing was asked, so nothing is worth spotting
		return theme.DimStyle
	}
}

// renderDetailsContent draws one check: what was observed, what it means, what
// to do, and the facts behind it.
func (m *Model) renderDetailsContent(width int) string {
	c := m.selected
	e := netcheck.Explain(c)

	var lines []string
	lines = append(lines, theme.EmptyLineBg(width))
	lines = append(lines, section(width, "Observed", e.Observed)...)
	lines = append(lines, section(width, "What it means", e.Means)...)
	if e.Do != "" {
		lines = append(lines, section(width, "What to do", e.Do)...)
	}

	if len(c.Facts) > 0 {
		lines = append(lines, theme.PadWithBg(theme.SubTitleStyle.Render(theme.IconConfig+" Details"), width))
		lines = append(lines, theme.EmptyLineBg(width))
		for _, f := range c.Facts {
			line := theme.KeyStyle.Render("  "+f.Key+" "+theme.IconChevronRight+" ") + theme.Bg(f.Value)
			lines = append(lines, theme.PadWithBg(line, width))
		}
		lines = append(lines, theme.EmptyLineBg(width))
	}

	if len(c.Phases) > 0 {
		lines = append(lines, theme.PadWithBg(theme.SubTitleStyle.Render(theme.IconConfig+" Timing"), width))
		lines = append(lines, theme.EmptyLineBg(width))
		lines = append(lines, phaseLines(c.Phases, c.Duration, width)...)
		lines = append(lines, theme.EmptyLineBg(width))
	}

	return strings.Join(lines, "\n")
}

// phaseLabelWidth fits the longest phase name ("Connect"/"Content", 7
// characters) plus one cell of breathing room before the bar starts.
const phaseLabelWidth = 8

// phaseLines renders one waterfall row per phase: a label, a bar proportional
// to the phase's share of total, and that share as a percentage. total is
// the check's own Duration — the phases already sum to it (see httpPhases),
// so the same value anchors both the bars and the numbers beside them.
func phaseLines(phases []netcheck.Phase, total time.Duration, width int) []string {
	lines := make([]string, 0, len(phases))
	for _, p := range phases {
		var pct float64
		if total > 0 {
			pct = float64(p.Duration) / float64(total) * 100
		}
		fill := theme.GaugeFillWidth(pct, theme.TimingBarWidth)
		bar := theme.TimingFillStyle().Render(theme.GaugeFill(fill)) +
			theme.GaugeTrackStyle().Render(theme.GaugeTrack(theme.TimingBarWidth-fill))
		label := theme.KeyStyle.Render(fmt.Sprintf("  %-*s", phaseLabelWidth, p.Name))
		pctText := theme.Bg(fmt.Sprintf(" %3.0f%%", pct))
		lines = append(lines, theme.PadWithBg(label+bar+pctText, width))
	}
	return lines
}

// section renders a titled block of prose, wrapped to the pane.
func section(width int, title, body string) []string {
	if strings.TrimSpace(body) == "" {
		return nil
	}
	lines := []string{
		theme.PadWithBg(theme.SubTitleStyle.Render(theme.IconConfig+" "+title), width),
		theme.EmptyLineBg(width),
	}
	wrapped := lipgloss.NewStyle().Width(max(width-4, 20)).Render(body)
	for line := range strings.SplitSeq(wrapped, "\n") {
		lines = append(lines, theme.PadWithBg(theme.Bg("  "+line), width))
	}
	lines = append(lines, theme.EmptyLineBg(width))
	return lines
}

// rebuildChecksTable refills the table from the filtered results.
func (m *Model) rebuildChecksTable() {
	m.checksTable.SetItems(m.visibleChecks())
	m.checksTable.Resize(m.width, max(m.height-13, 3))
}

func (m *Model) resizeInputs() {
	// Viewport border (2) + form padding (2) + prefix (2) + longest label "DNS Server " + chevron + spaces (~15)
	const labelOverhead = 21
	wide := max(m.width-labelOverhead, 20)
	m.targetInput.SetWidth(wide)
	m.dnsServerInput.SetWidth(wide)
	m.portInput.SetWidth(10)
}

func (m *Model) resizeDetailsViewport() {
	// Header ~9 lines + tab footer 3 lines + viewport border 2 lines = 14 overhead
	m.detailsViewport = viewport.New(viewport.WithWidth(max(m.width-4, 20)), viewport.WithHeight(max(m.height-13, 3)))
	m.detailsViewport.Style = lipgloss.NewStyle().Background(theme.ColorBackground)
}

// progressLabel names the question being asked, so a wait on a slow stage is
// legible rather than mute.
func (m *Model) progressLabel() string {
	return fmt.Sprintf("%s (%d/%d)", netcheck.StageTitle(m.runStage), m.runStep+1, m.totalSteps)
}

