259		case m.activeTab == tabDiagnostics && m.filterBar.IsVisible():
260			parts = append(parts, m.filterBar.View())
261		case m.activeTab == tabInterfaces && m.interfacesModel.table.FilterBar().IsVisible():
262			parts = append(parts, m.interfacesModel.table.FilterBar().View())
